import SwiftUI
struct BookingsView:View{@EnvironmentObject private var store:AppStore;@State private var reviewBooking:Booking?;@State private var disputeBooking:Booking?;var body:some View{NavigationStack{ScrollView{VStack(alignment:.leading,spacing:18){Text("Your bookings").font(DopenexaFont.display(30));if store.bookings.isEmpty{VStack(spacing:12){Image(systemName:"calendar.badge.plus").font(.system(size:44)).foregroundStyle(DopenexaColor.brand);Text("Nothing booked yet").font(DopenexaFont.title());Text("Your live bookings will appear here.").multilineTextAlignment(.center).font(DopenexaFont.body()).foregroundStyle(DopenexaColor.muted)}.frame(maxWidth:.infinity).padding(40).dopenexaCard()}else{ForEach(store.bookings){ booking in VStack(alignment:.leading,spacing:10){NavigationLink { ProjectView(booking: booking) } label: { BookingCard(booking:booking) }.buttonStyle(.plain); if booking.status == "completed" { Button("Leave a review") { reviewBooking=booking }.font(DopenexaFont.label()) }; if ["pending","confirmed","in_progress"].contains(booking.status) { Button("Report an issue") { disputeBooking=booking }.font(DopenexaFont.label()).foregroundStyle(.red) }} }}}.padding(20)}.background(DopenexaColor.surface.ignoresSafeArea()).task{await store.loadBookings()}.sheet(item:$reviewBooking){ReviewSheet(booking:$0)}.sheet(item:$disputeBooking){DisputeSheet(booking:$0)}}}}
private struct BookingCard:View{let booking:Booking;var body:some View{VStack(alignment:.leading,spacing:14){HStack{DopenexaPill(text:booking.status.capitalized,icon:"checkmark.seal.fill");Spacer();Text("₦\(booking.totalNGN.formatted())").font(DopenexaFont.title(17))};Text("Booking \(booking.id.prefix(8))").font(DopenexaFont.title(19));Divider();HStack{Label(booking.startsAt.formatted(date:.abbreviated,time:.shortened),systemImage:"calendar");Spacer();Text("Live booking").font(DopenexaFont.label()).foregroundStyle(DopenexaColor.brand)}.font(DopenexaFont.label())}.dopenexaCard()}}
